from solution import exchange
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st
import random


def ref(lst1, lst2):
    odds = sum(1 for x in lst1 if x % 2 != 0)
    evens = sum(1 for x in lst2 if x % 2 == 0)
    return "YES" if odds <= evens else "NO"


def test_spec_example_1():
    assert exchange([1, 2, 3, 4], [1, 2, 3, 4]) == "YES"


def test_spec_example_2():
    assert exchange([1, 2, 3, 4], [1, 5, 3, 4]) == "NO"


def test_return_values_are_exact():
    @given(
        st.lists(st.integers(-100, 100), min_size=1, max_size=10),
        st.lists(st.integers(-100, 100), min_size=1, max_size=10),
    )
    def inner(lst1, lst2):
        r = exchange(lst1, lst2)
        assert r == "YES" or r == "NO"
        assert isinstance(r, str)
        assert r in ("YES", "NO")

    inner()


@given(
    st.lists(st.integers(-1000, 1000).filter(lambda x: x % 2 == 0), min_size=1, max_size=10),
    st.lists(st.integers(-1000, 1000), min_size=1, max_size=10),
)
def test_all_even_lst1_always_yes(lst1, lst2):
    # No exchange needed; lst1 already all even.
    assert exchange(lst1, lst2) == "YES"


@given(
    st.lists(st.integers(-1000, 1000).filter(lambda x: x % 2 != 0), min_size=1, max_size=10),
    st.lists(st.integers(-1000, 1000).filter(lambda x: x % 2 != 0), min_size=1, max_size=10),
)
def test_odd_lst1_no_even_lst2_always_no(lst1, lst2):
    # lst1 needs at least one replacement but lst2 has nothing to give.
    assert exchange(lst1, lst2) == "NO"


@given(
    st.lists(st.integers(-100, 100), min_size=1, max_size=12),
    st.lists(st.integers(-100, 100), min_size=1, max_size=12),
)
def test_count_condition_equivalence_to_reference(lst1, lst2):
    assert exchange(lst1, lst2) == ref(lst1, lst2)


@given(
    st.lists(st.integers(-50, 50), min_size=1, max_size=8),
    st.lists(st.integers(-50, 50), min_size=1, max_size=8),
)
def test_permutation_invariance(lst1, lst2):
    # Order does not matter, only counts of odd/even.
    r = exchange(lst1, lst2)
    p1 = list(lst1)
    p2 = list(lst2)
    random.Random(0).shuffle(p1)
    random.Random(1).shuffle(p2)
    assert exchange(p1, p2) == r
    assert exchange(list(reversed(lst1)), list(reversed(lst2))) == r


@given(
    st.lists(st.integers(-100, 100), min_size=1, max_size=10),
    st.lists(st.integers(-100, 100), min_size=1, max_size=10),
    st.integers(-100, 100).filter(lambda x: x % 2 == 0),
)
def test_monotonic_adding_even_to_lst2_preserves_yes(lst1, lst2, even_extra):
    assume(exchange(lst1, lst2) == "YES")
    assert exchange(lst1, lst2 + [even_extra]) == "YES"


@given(
    st.lists(st.integers(-100, 100), min_size=1, max_size=10),
    st.lists(st.integers(-100, 100), min_size=1, max_size=10),
)
def test_monotonic_replacing_odd_with_even_preserves_yes(lst1, lst2):
    assume(exchange(lst1, lst2) == "YES")
    # Replace every odd in lst1 with an even: must stay YES.
    fixed = [x if x % 2 == 0 else 0 for x in lst1]
    assert exchange(fixed, lst2) == "YES"
    # Removing an odd (replace with even) cannot turn YES into NO.
    for i, x in enumerate(lst1):
        if x % 2 != 0:
            lst1b = list(lst1)
            lst1b[i] = 2
            assert exchange(lst1b, lst2) == "YES"


@given(
    st.lists(st.integers(-100, 100), min_size=1, max_size=10),
    st.lists(st.integers(-100, 100), min_size=1, max_size=10),
    st.integers(-100, 100).filter(lambda x: x % 2 != 0),
)
def test_adding_odd_to_lst2_does_not_change_result(lst1, lst2, odd_extra):
    # Odd elements in lst2 are useless for fixing lst1, so result unchanged.
    assert exchange(lst1, lst2 + [odd_extra]) == exchange(lst1, lst2)


@given(
    st.integers(1, 10),
    st.integers(0, 10),
)
def test_boundary_exact_counts(n_odd, n_even_extra):
    # lst1 has exactly n_odd odds; lst2 has exactly n_odd + n_even_extra evens
    # (padded with odds which are irrelevant). Boundary: YES iff n_even_extra >= 0.
    # Here it is always YES; removing one even flips to NO when n_even_extra == 0.
    lst1 = [1] * n_odd + [2]
    lst2_full = [0] * (n_odd + n_even_extra) + [1]
    assert exchange(lst1, lst2_full) == "YES"
    if n_even_extra == 0 and n_odd >= 1:
        # One fewer even than needed -> NO (touching off-by-one).
        lst2_short = [0] * (n_odd - 1) + [1]
        assert exchange(lst1, lst2_short) == "NO"


def test_zero_is_even():
    assert exchange([1], [0]) == "YES"
    assert exchange([0, 2, 4], [1, 3, 5]) == "YES"
    assert exchange([1, 3], [0, 1]) == "NO"


def test_negative_numbers_parity():
    assert exchange([-1, -3, 2], [-2, 1]) == "NO"
    assert exchange([-1, -3, 2], [-2, -4, 1]) == "YES"
    assert exchange([-2, -4], [-1]) == "YES"


def test_single_element_cases():
    assert exchange([2], [1]) == "YES"
    assert exchange([1], [2]) == "YES"
    assert exchange([1], [3]) == "NO"
    assert exchange([2], [4]) == "YES"
